use crate::position::AccountBalance;
use super::record;

/// Merge derived balances under observed ones — **the observed wins on the same day**.
///
/// Both are observations, so neither is categorically better; the tie-break is which one a person
/// can correct. A statement's closing figure is fixed by the export, while a balance somebody typed
/// is what they were looking at in the account — often BECAUSE the derived one looked wrong. Letting
/// the derivation overwrite that would make the correction impossible to express, and it would do it
/// silently, which is the part that matters.
///
/// A stored balance on any OTHER day is kept as its own observation rather than replacing anything —
/// [`record`]'s same-account-same-day rule is the whole of the collision policy.
pub fn prefer_observed(stored: &[AccountBalance], derived: &[AccountBalance]) -> Vec<AccountBalance> {
    let mut out = derived.to_vec();
    for b in stored {
        record(&mut out, b.clone());
    }
    out
}
